// Usage: node <this-file> /tmp/fdc-real-data.json /tmp/fdc-observed-browser.png
// Input contains {observed, oracle}; generated by the read-only artifact probe.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { createRequire } from 'node:module';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../../..');
const require = createRequire(resolve(root, 'wepppy/weppcloud/static-src/package.json'));
const { chromium } = require('@playwright/test');
const fixture = JSON.parse(await readFile(process.argv[2], 'utf8'));
const modules = resolve(root, 'wepppy/weppcloud/static/js/gl-dashboard');
const html = `<!doctype html><html><head><style>:root { --wc-color-text: #263445; } body { font: 16px sans-serif; padding: 16px; } label { margin-right: 12px; }</style><title>Observed flow-duration verification</title></head>
<body><h1>Observed flow-duration verification</h1><div id="graphs"></div>
<div id="gl-graph"><div id="gl-graph-empty"></div><div id="gl-graph-container" style="width:1000px;height:550px">
<canvas id="gl-graph-canvas"></canvas></div><div id="gl-graph-tooltip"></div></div>
<script type="module">
import {createGraphController} from '/modules/graphs/controller.js';
import {createGraphLoaders} from '/modules/graphs/graph-loaders.js';
import {createTimeseriesGraph} from '/modules/graphs/timeseries-graph.js';
import {getState,setValue} from '/modules/state.js';
const fixture=await (await fetch('/fixture.json')).json();
const metadata={observed:fixture.observed,scenarios:{'':{hillslope:{available:true},outlet:{available:true,channelId:1,elementId:1}}}};
const graph=createTimeseriesGraph(); graph.init(); window.graph=graph;
const query=async(payload)=>({records:[{year:2000,month:1,day:1,julian:1,flow:payload.columns.some(v=>v.includes(' AS area'))?'1':'86400',area:'86400000'}],row_count:1});
const noop=()=>{};
const controller=createGraphController({
 graphDefs:[{key:'flow-duration',title:'Flow Duration',items:[{key:'flow-duration',label:'Flow duration curve',type:'flow-duration'}]}],
 graphScenarios:[{path:'',name:'Base'}],flowDuration:metadata,
 graphLoadersFactory:()=>createGraphLoaders({graphScenarios:[{path:'',name:'Base'}],flowDuration:metadata,postQueryEngineForScenario:query}),
 getState,setValue,timeseriesGraph:graph,graphListEl:document.getElementById('graphs'),graphEmptyEl:document.getElementById('gl-graph-empty'),
 graphModeController:{clearGraphModeOverride:noop,setGraphFocus:noop,setGraphMode:noop,syncGraphLayout:noop,ensureGraphExpanded:noop}
});
setValue('graphMode','split');
setValue('flowDuration',{source:'hillslope',excludedYears:0,scale:'linear',includeObserved:false});
controller.renderGraphList(); document.querySelector('details').open=true;
await controller.activateGraphItem('flow-duration'); window.ready=true;
</script></body></html>`;
const server = createServer(async (req, res) => {
  try {
    if (req.url === '/') { res.setHeader('Content-Type', 'text/html'); res.end(html); return; }
    if (req.url === '/fixture.json') { res.setHeader('Content-Type', 'application/json'); res.end(JSON.stringify(fixture)); return; }
    const path = resolve(modules, req.url.replace(/^\/modules\//, ''));
    if (!req.url.startsWith('/modules/') || !path.startsWith(modules + '/')) { res.writeHead(404).end(); return; }
    res.setHeader('Content-Type', 'text/javascript'); res.end(await readFile(path));
  } catch { res.writeHead(404).end(); } // Local test server boundary only.
});
await new Promise(done => server.listen(0, '127.0.0.1', done));
const browser = await chromium.launch({headless:true});
try {
  const page = await browser.newPage({viewport:{width:1280,height:1100}});
  const errors=[]; page.on('pageerror',error=>errors.push(error.message));
  await page.goto(`http://127.0.0.1:${server.address().port}`);
  await page.waitForFunction(()=>window.ready);
  assert.equal(await page.evaluate(()=>graph._data.series.length),1);
  await page.getByLabel('Show observed streamflow').check();
  await page.waitForFunction(()=>window.graph._data?.series.some(s=>s.id==='observed'));
  const check=async()=>{
    const result=await page.evaluate(()=>{const s=graph._data.series.find(s=>s.id==='observed');return {count:s.count,maxFlow:s.points[0].flow,minFlow:s.points.at(-1).flow,firstProbability:s.points[0].probability};});
    assert.deepEqual(result,fixture.oracle);
    assert.match(await page.locator('.gl-flow-duration-info').innerText(),/Observed:/);
    assert.match(await page.locator('[aria-live="polite"]').innerText(),/Observed:.*m³\/s/);
  };
  await check();
  await page.getByLabel('Channel outlet discharge',{exact:true}).check();
  await page.waitForFunction(()=>window.graph._data?.settings.source==='outlet');
  await check();
  await page.locator('#fdc-year-selection').selectOption('5');
  await page.waitForFunction(()=>window.graph._data?.settings.excludedYears===5);
  await check();
  await page.getByLabel('Logarithmic',{exact:true}).check();
  await page.waitForFunction(()=>window.graph._data?.settings.scale==='log');
  await check();
  await page.screenshot({path:process.argv[3]||'/tmp/fdc-observed-browser.png',fullPage:true});
  await page.getByLabel('Show observed streamflow').uncheck();
  await page.waitForFunction(()=>window.graph._data?.series.length===1);
  assert.deepEqual(errors,[]);
  console.log(JSON.stringify({status:'passed',oracle:fixture.oracle,checks:['real artifact values','controller/loader/renderer wiring','both sources','simulation warm-up independence','log axis','keyboard values','toggle off'],pageErrors:errors}));
} finally { await browser.close(); await new Promise(done=>server.close(done)); }
